entries[7256] = { ["name"] = "Schattenschutztrank", ["text"] = "Wirken in 3 sek.\nReagenzien:\nGrabmoos , Königsblut , Verbleite Phiole\n17\nBenutzen: Absorbiert 675 bis 1125 Schattenschaden. Hält 2 Min. lang an. (2 Min Abklingzeit)" }
