entries[7278] = { ["name"] = "Sammlerschwarm beschwören", ["text"] = "Sofort\nBeschwört 1 Sammlerschwarm, um dem Zaubernden 2 Min. lang im Kampf zu helfen." }
entries[7279] = { ["name"] = "Schwarzer Schlamm", ["text"] = "Nahkampfreichweite\nWirken in 3 sek.\nErhöht die Zeit zwischen Angriffen in der Nähe befindlicher Feinde um 50% und verlangsamt ihr Bewegungstempo um 30%. Hält 30 Sek. lang an." }
entries[7285] = { ["name"] = "Horn der Maraudine blasen", ["text"] = "5 Meter Reichweite\nSofort\nDas Kriegshorn der Maraudine platzieren und blasen." }
entries[7289] = { ["name"] = "Schrumpfen", ["text"] = "30 Meter Reichweite\nWirken in 3 sek.\nVerringert die Stärke eines Feindes um 1 und seine Ausdauer 2 Min. lang um 1." }
entries[7290] = { ["name"] = "Seelenentzug", ["text"] = "10 Mana 10 Meter Reichweite\nKanalisiert (Wirken in 10 sek.) 1 sek. Abklingzeit\nZieht 10 Sek. lang insgesamt 10 Gesundheit von einem Feind ab und heilt den Zaubernden um den maximal zweifachen Wert der gestohlenen Gesundheit." }
entries[7293] = { ["name"] = "Zombiegestalt" }
entries[7294] = { ["name"] = "Aura der Vergeltung", ["text"] = "Sofort\nVerursacht 5 Heiligschaden für jede Kreatur, die ein Gruppenmitglied schlägt, das sich im Umkreis von 30 Metern befindet. Die Spieler können pro Paladin nur jeweils eine Aura besitzen." }
entries[7295] = { ["name"] = "Seelensauger", ["text"] = "40 Meter Reichweite\nWirken in 2 sek.\nMacht einen Feind 10 Sek. lang bewegungsunfähig, entzieht 35 Gesundheit und überträgt sie auf den Zaubernden." }
entries[7300] = { ["name"] = "Frostrüstung", ["text"] = "110 Mana\nSofort\nErhöht die Rüstung um 110. Wenn ein Feind den Zaubernden schlägt, kann 5 Sek. lang sein Bewegungstempo um 30% verlangsamt und die Zeit zwischen Angriffen um 25% erhöht werden. Es kann immer nur ein Rüstungszauber zur selben Zeit auf dem Magier aktiv sein. Hält 30 Min. lang an." }
entries[7301] = { ["name"] = "Frostrüstung", ["text"] = "170 Mana\nSofort\nErhöht die Rüstung um 200. Wenn ein Feind den Zaubernden schlägt, kann 5 Sek. lang sein Bewegungstempo um 30% verlangsamt und die Zeit zwischen Angriffen um 25% erhöht werden. Es kann immer nur ein Rüstungszauber zur selben Zeit auf dem Magier aktiv sein. Hält 30 Min. lang an." }
entries[7302] = { ["name"] = "Eisrüstung", ["text"] = "240 Mana\nSofort\nErhöht die Rüstung um 290 und den Frostwiderstand um 6. Wenn ein Feind den Zaubernden schlägt, kann 5 Sek. lang sein Bewegungstempo um 30% verlangsamt und die Zeit zwischen seinen Angriffen um 25% erhöht werden. Es kann immer nur ein Rüstungszauber zur selben Zeit auf dem Magier aktiv sein. Hält 30 Min. lang an." }
entries[7320] = { ["name"] = "Eisrüstung", ["text"] = "320 Mana\nSofort\nErhöht die Rüstung um 380 und den Frostwiderstand um 9. Wenn ein Feind den Zaubernden schlägt, kann 5 Sek. lang sein Bewegungstempo um 30% verlangsamt und die Zeit zwischen seinen Angriffen um 25% erhöht werden. Es kann immer nur ein Rüstungszauber zur selben Zeit auf dem Magier aktiv sein. Hält 30 Min. lang an." }
entries[7321] = { ["name"] = "Kälte" }
entries[7322] = { ["name"] = "Frostblitz", ["text"] = "65 Mana 30 Meter Reichweite\nWirken in 2.6 sek.\nSchleudert einen Frostblitz auf den Feind, der 78 bis 87 Frostschaden verursacht und 7 Sek. lang das Bewegungstempo um 40% reduziert." }
entries[7328] = { ["name"] = "Erlösung", ["text"] = "64% von Grundmana 30 Meter Reichweite\nWirken in 10 sek.\nBringt einen Spieler mit 65 Gesundheit und 120 Mana ins Leben zurück. Kann nicht während des Kampfes verwendet werden." }
