entries[7342] = { ["name"] = "Weiter Streich", ["text"] = "Nahkampfreichweite\nNächster Nahkampf\nFügt Feinden in einem kegelförmigen Bereich vor dem Zaubernden normalen Schaden plus 5 zu." }
entries[7344] = { ["name"] = "Rekombobulieren" }
entries[7353] = { ["name"] = "Gemütliches Feuer", ["text"] = "Sofort\nErhöht Eure Willenskraft um 4." }
entries[7355] = { ["name"] = "Feststecken", ["text"] = "Wirken in 10 sek." }
entries[7356] = { ["name"] = "Wache rufen" }
entries[7357] = { ["name"] = "Giftiger Stich", ["text"] = "Nahkampfreichweite\nSofort 30 sek. Abklingzeit\nVerursacht alle 3 Sek. 16 Naturschaden bei einem Feind, erhöht die Zeit zwischen seinen Angriffen um 25% und verlangsamt sein Bewegungstempo um 63%. Hält 15 Sek. lang an." }
entries[7358] = { ["name"] = "Gemütliches Feuer", ["text"] = "Sofort\nErhöht Eure Willenskraft um 8." }
entries[7359] = { ["name"] = "Helles Lagerfeuer", ["text"] = "Wirken in 10 sek. 5 min Abklingzeit\nTools: Feuerstein und Zunder\nReagenzien:\nEinfaches Holz\nBaut ein Lagerfeuer, das die Willenskraft von jedem in der Nähe um 8 erhöht und das Kochen ermöglicht." }
entries[7363] = { ["name"] = "Feuerleuchten", ["text"] = "Sofort 1 sek. Abklingzeit\nErhöht die Willenskraft der in der Nähe befindlichen Gruppenmitglieder um 4." }
entries[7364] = { ["name"] = "Lichtfackel" }
entries[7365] = { ["name"] = "Flasche Gift", ["text"] = "Nahkampfreichweite\nSofort 1 min Abklingzeit\nWirft eine Flasche Gift auf den Feind und fügt ihm 30 Sek. lang alle 3 Sek. 19 Naturschaden zu." }
entries[7366] = { ["name"] = "Berserkerhaltung", ["text"] = "Sofort\nNimmt eine aggressive Haltung ein, die Wut erzeugt, wenn der Krieger einen Gegner schlägt. Hält 4 Min. lang an." }
entries[7367] = { ["name"] = "Infizierter Biss", ["text"] = "Nahkampfreichweite\nSofort\nVerursacht alle 5 Sek. 10 Naturschaden bei einem Feind und erhöht seinen erlittenen körperlichen Schaden um 5. Hält 30 Sek. lang an." }
entries[7369] = { ["name"] = "Spalten", ["text"] = "20 Wut Nahkampfreichweite\nNächster Nahkampf\nBenötigt Nahkampfwaffe\nEin weitreichender Angriff, der dem Ziel und seinem nächsten Verbündeten Euren Waffenschaden sowie 10 zusätzlichen Schaden zufügt." }
entries[7370] = { ["name"] = "Sturmangriff" }
entries[7371] = { ["name"] = "Sturmangriff", ["text"] = "35 Fokus 8 - 25 Meter Reichweite\nSpontanzauber 25 sek. Abklingzeit\nAuf einen Feind zustürmen, wobei er 1 Sek. lang bewegungsunfähig wird und außerdem die Nahkampfangriffskraft des Ebers beim nächsten Angriff um 60 erhöht wird." }
entries[7372] = { ["name"] = "Kniesehne", ["text"] = "10 Wut Nahkampfreichweite\nSpontanzauber\nBenötigt Nahkampfwaffe\nBenötigt Kampfhaltung, Berserkerhaltung\nVerstümmelt den Feind, wobei 18 Schaden verursacht werden und die Bewegung des Feindes 15 Sek. lang auf 45% des normalen Tempos verlangsamt wird." }
entries[7373] = { ["name"] = "Kniesehne", ["text"] = "10 Wut Nahkampfreichweite\nSpontanzauber\nBenötigt Nahkampfwaffe\nBenötigt Kampfhaltung, Berserkerhaltung\nVerstümmelt den Feind, wobei 45 Schaden verursacht werden und die Bewegung des Feindes 15 Sek. lang um 50% verlangsamt wird." }
entries[7376] = { ["name"] = "Verteidigungshaltung - Passiv", ["text"] = "Verringert den aus jeglichen Quellen erlittenen Schaden um 10%. Verringert zugefügten Schaden um 10%.\nErhöht erzeugte Bedrohung um 30%." }
entries[7377] = { ["name"] = "Periodischen Immunschaden nehmen" }
entries[7379] = { ["name"] = "Rache", ["text"] = "5 Wut Nahkampfreichweite\nSpontanzauber 5 sek. Abklingzeit\nBenötigt Nahkampfwaffe\nBenötigt Verteidigungshaltung\nFührt einen sofortigen Gegenangriff gegen den Feind aus, der 107 bis 129 Schaden verursacht und dabei ein hohes Maß an Bedrohung generiert. 'Rache' muss auf Blocken, Ausweichen oder Parieren folgen." }
entries[7381] = { ["name"] = "Berserkerhaltung - Passiv", ["text"] = "Erhöht Chance auf kritischen Treffer um 3%.\nErhöht jeglichen erlittenen Schaden um 10%.\nVerringert erzeugte Bedrohung um 20%." }
entries[7383] = { ["name"] = "Wasserblase" }
entries[7384] = { ["name"] = "Überwältigen", ["text"] = "5 Wut Nahkampfreichweite\nSpontanzauber 5 sek. Abklingzeit\nBenötigt Nahkampfwaffe\nBenötigt Kampfhaltung\nSofortige Überwältigung des Feindes, wodurch Waffenschaden plus 5 entsteht. Kann nur nach Ausweichen durch das Ziel verwendet werden. Auf 'Überwältigen' kann nicht mit Blocken, Ausweichen oder Parieren reagiert werden." }
entries[7386] = { ["name"] = "Rüstung zerreißen", ["text"] = "15 Wut Nahkampfreichweite\nSpontanzauber\nBenötigt Nahkampfwaffe\nZerreißt die Rüstung des Ziels, verringert sie um 90 pro Einsatz von 'Rüstung zerreißen' und verursacht ein hohes Maß an Bedrohung. Kann bis zu 5-mal angewendet werden. Hält 30 Sek. lang an." }
entries[7389] = { ["name"] = "Angreifen", ["text"] = "100 Meter Reichweite\nWirken in 2 sek.\nErhöht 15 Sek. lang das Angriffstempo des Tiers des Zaubernden um 50%." }
entries[7393] = { ["name"] = "Bruder heilen", ["text"] = "60 Meter Reichweite\nSofort\nHeilt das Ziel um 30000." }
entries[7394] = { ["name"] = "Drehender Streich", ["text"] = "Nahkampfreichweite\nNächster Nahkampf\nVerursacht normalen Schaden plus 5 bei in der Nähe befindlichen Feinden." }
entries[7395] = { ["name"] = "Todesminendynamit", ["text"] = "30 Meter Reichweite\nWirken in 2 sek.\nFügt allen Feinden in einem ausgewählten Gebiet 43 bis 57 Feuerschaden zu." }
entries[7396] = { ["name"] = "Lebertran", ["text"] = "Sofort\nErhöht Eure Nahkampftempowertung 30 Sek. lang um 100." }
entries[7398] = { ["name"] = "Geburt" }
entries[7399] = { ["name"] = "Erschrecken", ["text"] = "Nahkampfreichweite\nSofort\nErschreckt einen Feind und lässt ihn 4 Sek. lang voller Furcht flüchten. Es kann immer nur jeweils ein einzelnes Ziel mit Schrecken erfüllt werden." }
entries[7400] = { ["name"] = "Spöttischer Schlag", ["text"] = "10 Wut Nahkampfreichweite\nSpontanzauber 2 min Abklingzeit\nBenötigt Nahkampfwaffe\nBenötigt Kampfhaltung\nEin spottender Angriff, der 31 Schaden und ein mittleres Maß an Bedrohung verursacht. Zwingt das Ziel 6 Sek. lang dazu, Angriffe auf Euch zu fokussieren." }
entries[7402] = { ["name"] = "Spöttischer Schlag", ["text"] = "10 Wut Nahkampfreichweite\nSpontanzauber 2 min Abklingzeit\nBenötigt Nahkampfwaffe\nBenötigt Kampfhaltung\nEin spottender Angriff, der 46 Schaden und ein mittleres Maß an Bedrohung verursacht. Zwingt das Ziel 6 Sek. lang dazu, Angriffe auf Euch zu fokussieren." }
entries[7405] = { ["name"] = "Rüstung zerreißen", ["text"] = "15 Wut Nahkampfreichweite\nSpontanzauber\nBenötigt Nahkampfwaffe\nZerreißt die Rüstung des Ziels, verringert sie um 180 pro Einsatz von 'Rüstung zerreißen' und verursacht ein hohes Maß an Bedrohung. Kann bis zu 5-mal angewendet werden. Hält 30 Sek. lang an." }
entries[7408] = { ["name"] = "Schwerer Kupferschlägel", ["text"] = "Wirken in 8 sek.\nTools: Schmiedehammer\nReagenzien:\nKupferbarren (12), Schwacher Fluxus (2), Leichtes Leder (2)\nZweihändig Streitkolben\n21 - 32 Schaden Tempo 2.80\n(9.46 Schaden pro Sekunde)\nHaltbarkeit 55 / 55\n11" }
entries[7411] = { ["name"] = "Verzauberkunst", ["text"] = "Sofort\nErmöglicht einem Verzauberer, Standard-Gegenstände mit einer maximalen potenziellen Fertigkeit von 75 zu verzaubern. Es werden Staub und Essenzen benötigt, die durch Entzaubern von magischen Gegenständen gefunden wurden." }
entries[7412] = { ["name"] = "Verzauberkunst", ["text"] = "Sofort\nErmöglicht einem Verzauberer das Verzaubern von Waffen und Rüstung mit einer maximalen potenziellen Fertigkeit von 150." }
entries[7413] = { ["name"] = "Verzauberkunst", ["text"] = "Sofort\nErmöglicht einem Verzauberer das meisterhafte Verzaubern von Waffen und Rüstung mit einer maximalen potenziellen Fertigkeit von 225." }
entries[7414] = { ["name"] = "Verzauberkunstlehrling" }
entries[7415] = { ["name"] = "Verzauberkunstgeselle" }
entries[7416] = { ["name"] = "Verzauberkunstexperte" }
entries[7418] = { ["name"] = "Armschiene - Schwache Gesundheit", ["text"] = "Wirken in 5 sek.\nBenötigt Armschienen\nTools: Runenverzierte Kupferrute\nReagenzien:\nSeltsamer Staub\nArmschienen dauerhaft verzaubern, sodass die Gesundheit des Trägers um 5 erhöht wird." }
entries[7419] = { ["name"] = "Schwache Gesundheit" }
entries[7420] = { ["name"] = "Brust - Schwache Gesundheit", ["text"] = "Wirken in 5 sek.\nBenötigt Brust, Brust\nTools: Runenverzierte Kupferrute\nReagenzien:\nSeltsamer Staub\nEin Teil der Brustrüstung dauerhaft verzaubern, sodass die Gesundheit des Trägers um 5 erhöht wird." }
entries[7421] = { ["name"] = "Runenverzierte Kupferrute", ["text"] = "Wirken in 10 sek.\nReagenzien:\nKupferrute , Seltsamer Staub , Geringe Magieessenz\nWird beim Aufheben gebunden" }
entries[7423] = { ["name"] = "Schwache Absorption" }
entries[7426] = { ["name"] = "Brust - Schwache Absorption", ["text"] = "Wirken in 5 sek.\nBenötigt Brust, Brust\nTools: Runenverzierte Kupferrute\nReagenzien:\nSeltsamer Staub (2), Geringe Magieessenz\nEin Teil der Brustrüstung verzaubern, sodass bei jedem Treffer eine Chance von 2% besteht, Euch 10 Punkte Schadensabsorption zu geben." }
