entries[7623] = { ["name"] = "Braune Leinenrobe", ["text"] = "Wirken in 8 sek.\nReagenzien:\nLeinenstoffballen (3), Grober Faden\nBraune Leinenrobe\nWird beim Anlegen gebunden\nBrust Stoff\n19 Rüstung\n+1 Willenskraft\nHaltbarkeit 45 / 45\n5" }
