entries[7639] = { ["name"] = "Blauer Overall", ["text"] = "Wirken in 8 sek.\nReagenzien:\nWollstoffballen (4), Feiner Faden (2), Blauer Farbstoff (2)\nBlauer Overall\nWird beim Anlegen gebunden\nBrust Stoff\n34 Rüstung\n+4 Ausdauer\nHaltbarkeit 60 / 60\n15\nAnlegen: Erhöht durch Zauber und magische Effekte verursachten Schaden und Heilung um bis zu 5." }
entries[7641] = { ["name"] = "Schattenblitz", ["text"] = "210 Mana 30 Meter Reichweite\nWirken in 3 sek.\nSendet einen schattigen Blitz zum Gegner, der 213 bis 240 Schattenschaden verursacht." }
entries[7643] = { ["name"] = "Große Adeptenrobe", ["text"] = "Wirken in 12.5 sek.\nReagenzien:\nWollstoffballen (5), Feiner Faden (3), Roter Farbstoff (3)\nGroße Adeptenrobe\nWird beim Anlegen gebunden\nBrust Stoff\n37 Rüstung\n+1 Ausdauer\n+2 Intelligenz\n+7 Willenskraft\nHaltbarkeit 65 / 65\n18" }
