entries[7646] = { ["name"] = "Fluch der Schwäche", ["text"] = "95 Mana 30 Meter Reichweite\nSofort\nDie Nahkampfangriffskraft des Ziels wird 2 Min. lang um 82 reduziert. Es kann immer nur jeweils ein Fluch pro Hexenmeister auf einem beliebigen Ziel aktiv sein." }
entries[7648] = { ["name"] = "Verderbnis", ["text"] = "160 Mana 30 Meter Reichweite\nWirken in 2 sek.\nVerdirbt das Ziel und verursacht 18 Sek. lang insgesamt 324 Schattenschaden." }
entries[7651] = { ["name"] = "Blutsauger", ["text"] = "185 Mana 30 Meter Reichweite\nKanalisiert (Wirken in 5 sek.)\nÜberträgt alle 1 Sek. 41 Gesundheit vom Ziel auf den Zaubernden. Hält 5 Sek. lang an." }
entries[7655] = { ["name"] = "Verhexung von Rabenklaue", ["text"] = "30 Meter Reichweite\nWirken in 2 sek.\nVerflucht einen Feind, verringert den von ihm zugefügten körperlichen Schaden um 0 und reduziert seinen Magieschaden bis Abbruch lang um 0. Der Fluch erhöht außerdem den vom Zaubernden zugefügten körperlichen Schaden um 10 und verstärkt seinen Magieschaden 30 Sek. lang um 20." }
