entries[7658] = { ["name"] = "Fluch der Tollkühnheit", ["text"] = "60 Mana 30 Meter Reichweite\nSofort\nVerflucht das Ziel mit Tollkühnheit, wodurch sich die Nahkampfangriffskraft 2 Min. lang um 45 erhöht, jedoch die Rüstung um 290 verringert. Mit einem Fluch belegte Feinde fliehen nicht und ignorieren Furcht- und Entsetzenseffekte. Es kann immer nur jeweils ein Fluch pro Hexenmeister auf einem beliebigen Ziel aktiv sein." }
entries[7659] = { ["name"] = "Fluch der Tollkühnheit", ["text"] = "90 Mana 30 Meter Reichweite\nSofort\nVerflucht das Ziel mit Tollkühnheit, wodurch sich die Nahkampfangriffskraft 2 Min. lang um 65 erhöht, jedoch die Rüstung um 465 verringert. Mit einem Fluch belegte Feinde fliehen nicht und ignorieren Furcht- und Entsetzenseffekte. Es kann immer nur jeweils ein Fluch pro Hexenmeister auf einem beliebigen Ziel aktiv sein." }
